package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamPhysicsMechBank2 {
  private const val T = "යාන්ත්‍ර විද්‍යාව: මිනුම්, චලිතය, බලය, ශක්තිය හා ද්‍රවස්ථිතිය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "යාන්ත්‍ර විද්‍යාව හා මිනුම් පිළිබඳ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("භෞතික රාශි අතරින් 'ව්‍යුත්පන්න ඒකකයක්' (Derived unit) වන්නේ පහත සඳහන් කුමක්ද?", "නිව්ටන් (N) සහ ජූල් (J)", "මීටරය (m)", "තත්පරය (s)", "කෙල්වින් (K)", "නිව්ටන් යනු kg m s⁻² වන අතර මූලික ඒකකවලින් ව්‍යුත්පන්න කර ඇත."),
    q("සිලින්ඩරාකාර කුහරයක අභ්‍යන්තර විෂ්කම්භය මෙන්ම ගැඹුර ද 0.1 mm නිරවද්‍යතාවයකින් මැන ගැනීමට වඩාත් සුදුසු උපකරණය කුමක්ද?", "වර්නියර් කැලිපරය", "මයික්‍රෝමීටර ඉස්කුරුප්පුව", "සාමාන්‍ය මීටර කෝදුව", "මිලිමීටර මිනුම් පටිය", "වර්නියර් කැලිපරයේ අභ්‍යන්තර හනු, බාහිර හනු හා ගැඹුර මනින කූර පවතී."),
    q("මයික්‍රෝමීටර ඉස්කුරුප්පු ආමානයක කිසිවක් නොතබා හනු වසා ඇති විට වෘත්තාකාර පරිමාණයේ ශුන්‍යය දත්ත රේඛාවට පහළින් හෝ ඉහළින් පිහිටන්නේ නම් එම දෝෂය කුමක්ද?", "ශුන්‍ය දෝෂය (Zero error)", "අසම්මත දෝෂය", "ගුරුත්ව දෝෂය", "උෂ්ණත්ව දෝෂය", "නිවැරදි පාඨාංකය ලබා ගැනීමට මැනූ අගයෙන් ශුන්‍ය දෝෂය ශෝධනය කළ යුතුය."),
    q("රථයක් පැය 2 කදී කිලෝමීටර 144 ක් ගමන් කළේය. එහි සාමාන්‍ය වේගය m s⁻¹ වලින් කොපමණද?", "20 m s⁻¹", "72 m s⁻¹", "14.4 m s⁻¹", "40 m s⁻¹", "72 km h⁻¹ = 72 × (1000 / 3600) = 20 m s⁻¹."),
    q("ප්‍රවේග-කාල ප්‍රස්තාරයක් තිරස් කාල අක්ෂයට සමාන්තර සෘජු රේඛාවක් නම් එම වස්තුව ගමන් කරන්නේ කෙසේද?", "ඒකාකාර ප්‍රවේගයකින් ගමන් කරයි", "ඒකාකාර ත්වරණයකින් ගමන් කරයි", "සම්පූර්ණයෙන් නිසලව පවතී", "ක්‍රමයෙන් මන්දනය වෙමින් යයි", "කාලය ගත වුවද ප්‍රවේගය නියතව පවතී (v = නියත, a = 0)."),
    q("සෘජු මාර්ගයක ගමන් කරන මෝටර් රථයක් 10 m s⁻¹ සිට 30 m s⁻¹ දක්වා තත්පර 4 කින් වේගය වැඩි කරයි. එහි ත්වරණය හා එම කාලයේදී ගිය දුර කීයද?", "5 m s⁻², 80 m", "5 m s⁻², 40 m", "10 m s⁻², 80 m", "4 m s⁻², 60 m", "a = (30 - 10)/4 = 5 m s⁻²; s = ½(10 + 30) × 4 = 80 m."),
    q("වස්තුවක් මත ක්‍රියා කරන බල සියල්ල 'සමතුලිත' (Balanced forces) වූ විට සිදු විය හැකි දෙය කුමක්ද?", "නිසලව හෝ ඒකාකාර ප්‍රවේගයෙන් චලනය වීම", "වස්තුව ක්‍රමයෙන් ත්වරණය වීම", "වස්තුව ක්‍රමයෙන් මන්දනය වීම", "වස්තුව වෘත්තාකාර පථයක හැරීම", "සම්ප්‍රයුක්ත බලය ශුන්‍ය විට ත්වරණය ද ශුන්‍ය වේ."),
    q("ස්කන්ධය 8 kg වන බඳුනකට තිරස්ව 40 N බලයක් යෙදූ විට ඝර්ෂණ බලය 16 N කි. බඳුන ලබන ත්වරණය කීයද?", "3 m s⁻²", "5 m s⁻²", "2 m s⁻²", "7 m s⁻²", "සම්ප්‍රයුක්ත බලය = 40 - 16 = 24 N; a = 24 / 8 = 3 m s⁻²."),
    q("රේඛීය ගම්‍යතා සංස්ථිති නියමය අනුව 4 kg සහ 6 kg ස්කන්ධ දෙකක් ස්පර්ශව තබා අතර ඇති දුන්නක් මුදා හැරීමෙන් 6 kg ස්කන්ධය 2 m s⁻¹ වේගයෙන් ගියහොත් 4 kg ස්කන්ධයේ වේගය කීයද?", "3 m s⁻¹ (විරුද්ධ දිශාවට)", "2 m s⁻¹", "4 m s⁻¹", "1.33 m s⁻¹", "ආරම්භක ගම්‍යතාව 0 -> 4v = 6 × 2 → v = 3 m s⁻¹."),
    q("පන්දු රකින්නෙක් වේගයෙන් එන ක්‍රිකට් පන්දුවක් අල්ලා ගැනීමේදී අත පසුපසට ඇද ගන්නේ ඇයි?", "නැවතීමේ කාලය වැඩි කර අත මත බලය අඩු කිරීමට", "පන්දුවේ මුළු ස්කන්ධය අඩකින් අඩු කිරීමට", "පන්දුවේ රේඛීය ගම්‍යතාව තවත් වැඩි කිරීමට", "පන්දුව මත ගුරුත්වාකර්ෂණ බලය වැඩි කිරීමට", "F = Δ(mv) / Δt නිසා කාලය (Δt) වැඩි කළ විට ගැටුම් බලය (F) අඩු වේ."),
    q("එකිනෙකට ලම්භකව ක්‍රියා කරන 6 N සහ 8 N බල දෙකක සම්ප්‍රයුක්ත බලයේ විශාලත්වය කීයද?", "10 N", "14 N", "2 N", "48 N", "√(6² + 8²) = √(36 + 64) = 10 N."),
    q("යතුරක් (Spanner) මගින් තද කළ නට් එකක් ගැලවීමට දිග මිටක් ඇති යතුරක් භාවිත කිරීම පහසු වන්නේ ඇයි?", "අක්ෂයේ සිට දුර වැඩි විට වැඩි ඝූර්ණයක් ලැබීම", "දිග මිට නිසා යතුරේ ස්කන්ධය වැඩි වන බැවින්", "නට් එකේ විෂ්කම්භය ක්‍රමයෙන් කුඩා වන නිසා", "නට් එක හා යතුර අතර ඝර්ෂණය වැඩි වන නිසා", "කෙටි බලයකින් විශාල ඝූර්ණයක් (F × d) උපදවයි."),
    q("එකම විශාලත්වයෙන් යුත් සමාන්තර නමුත් ප්‍රතිවිරුද්ධ බල දෙකක් එකම රේඛාවේ නොවී වස්තුවක් මත ක්‍රියා කරන්නේ නම් එය කුමක්ද? (උදා: වාහන සුක්කානම)", "බල යුග්මයක් (Couple)", "සම්ප්‍රයුක්තයක්", "අවස්ථිතියක්", "ප්‍රතික්‍රියාවක්", "බල යුග්මයක ඝූර්ණය = එක් බලයක් × බල දෙක අතර ලම්භක දුර."),
    q("විදුලි පංකාවක පියාපත් කරකැවීමේදී ඒ මත ක්‍රියා කරන දෝලන/භ්‍රමණ බල යුග්මයේ අරමුණ කුමක්ද?", "රේඛීය චලිතයකින් තොර භ්‍රමණ චලිතයක් ඇති කිරීම", "පංකාව සිරස්ව ඉහළ දෙසට ඔසවා තැබීම", "පරිභෝජනය වන විදුලි ශක්තිය ඉතිරි කිරීම", "කැරකීමේදී පිටවන ශබ්දය වැඩි කර ගැනීම", "බල යුග්මයක සම්ප්‍රයුක්ත බලය ශුන්‍ය වන නමුත් ශුද්ධ ඝූර්ණයක් පවතී."),
    q("ක්ෂමතාවය මනින 'වොට් 1' (1 W) යන්න සමාන වන්නේ කුමන අගයටද?", "තත්පරයට ජූල් 1 (1 J s⁻¹)", "මීටරයට නිව්ටන් 1", "තත්පරයට නිව්ටන් 1", "ජූල් 100", "P = W / t බැවින් ක්ෂමතාව යනු කාර්යය කිරීමේ සීඝ්‍රතාවයයි."),
    q("විදුලි ජල පොම්පයක් මිනිත්තු 1 කින් 600 kg ක ජලය 10 m උස ටැංකියකට ඔසවයි නම් පොම්පයේ ප්‍රයෝජනවත් ක්ෂමතාව කීයද? (g = 10 m s⁻²)", "1,000 W (1 kW)", "60,000 W", "600 W", "100 W", "W = 600 × 10 × 10 = 60,000 J; t = 60 s -> P = 60,000 / 60 = 1,000 W."),
    q("සාමාන්‍යයෙන් චලනය වන වස්තුවක ප්‍රවේගය දෙගුණ කළහොත් එහි චාලක ශක්තියට කුමක් සිදුවේද?", "හතර ගුණයකින් වැඩි වේ (4×)", "දෙගුණ වේ (2×)", "අඩකින් අඩු වේ", "වෙනස් නොවේ", "Eₖ = ½mv² බැවින් වේගය 2× විට චාලක ශක්තිය 2² = 4 ගුණ වේ."),
    q("ගුරුත්වාකර්ෂණ විභව ශක්තිය හැරුණු විට රබර් පටියක් හෝ දුන්නක් ඇද තබන විට එහි ගබඩා වන ශක්ති ආකාරය කුමක්ද?", "ප්‍රත්‍යාස්ථ විභව ශක්තිය", "චාලක ශක්තිය", "රසායනික ශක්තිය", "න්‍යෂ්ටික ශක්තිය", "ඇදීම මුදා හැරිය විට එය චාලක ශක්තිය බවට පත්වේ."),
    q("සැබෑ යාන්ත්‍රික යන්ත්‍රයක ආදාන ශක්තියට වඩා ප්‍රතිදාන ප්‍රයෝජනවත් ශක්තිය සැමවිටම අඩු වන්නේ ඇයි?", "ඝර්ෂණය නිසා ශක්තිය තාපය හා ශබ්දය ලෙස අපතේ යාම", "යන්ත්‍රය තුළදී ශක්තිය මුළුමනින්ම විනාශ වීම", "යන්ත්‍රය මත ගුරුත්වාකර්ෂණ බලය ශුන්‍ය වී යාම", "චලනය වන කොටස්වල මුළු ස්කන්ධය වැඩි වී යාම", "කිසිම යන්ත්‍රයක කාර්යක්ෂමතාව 100% ඉක්මවිය නොහැක."),
    q("දිග 4 m වූ ආනත තලයක් ඔස්සේ 1.0 m උසට 600 N බරැති බැරලයක් පෙරළා ගැනීමට යොදන ආයාසය 200 N කි. ආනත තලයේ ප්‍රවේග අනුපාතය කීයද?", "4", "3", "200", "1.5", "VR = ආනත තලයේ දිග / සිරස් උස = 4 / 1.0 = 4 (මෙහි MA = 600/200 = 3; කාර්යක්ෂමතාව 75%)."),
    q("බොහෝ විට බර එසවීමට ගන්නා 4-කප්පි පද්ධතියක (Block and tackle system - කඹ කොටස් 4 ක් භාරය දරන) ප්‍රවේග අනුපාතය කීයද?", "4", "2", "1", "8", "පහළ කප්පි කුට්ටියට සම්බන්ධ කඹ කොටස් ගණන ප්‍රවේග අනුපාතයට සමාන වේ."),
    q("30 cm පැත්තක් ඇති ඝන ලී කුට්ටියක ඝනත්වය 600 kg m⁻³ වේ. ජලය (1000 kg m⁻³) මත තැබූ විට කුට්ටියට සිදුවන්නේ කුමක්ද?", "පරිමාවෙන් 60% ක් ජලයේ ගිලී පාවෙයි", "සම්පූර්ණයෙන් පතුලටම ගිලී රැඳී පවතී", "ජලය මත කිසිසේත් නොගිලී සම්පූර්ණයෙන් පාවෙයි", "කුට්ටිය ක්‍රමයෙන් ජලයේ දියවී අතුරුදහන් වේ", "ද්‍රව ඝනත්වයට වඩා වස්තුවේ ඝනත්වය අඩු නම් (600 < 1000), එය (600/1000) = 60% ක් ගිලී පාවෙයි."),
    q("නියත ස්කන්ධයක් ඇති වස්තුවක් මිරිදිය ජලාශයක සිට ලවණතාව වැඩි මුහුදට පිහිනන විට හෝ ගමන් කරන විට නැවට සිදුවන්නේ කුමක්ද?", "ඝනත්වය වැඩි නිසා නැව මඳක් ඉහළට එසවේ", "ඝනත්වය වැඩි නිසා නැව තවත් ගැඹුරට ගිලේ", "නැව ගිලී ඇති ගැඹුරේ කිසිදු වෙනසක් නොවේ", "ලවණතාව නිසා නැව අසමතුලිත වී පෙරළී යයි", "ප්ලිම්සෝල් රේඛා (Plimsoll lines) විවිධ ජල ඝනත්වවලදී නැවේ ආරක්ෂිත ගිලෙන මට්ටම පෙන්වයි."),
    q("සමුද්‍ර මට්ටමට වඩා ගැඹුරු 10 m යට සිටින කිමිදුම්කරුවෙකු මත ක්‍රියා කරන මුළු පීඩනය කොපමණද? (වායුගෝලීය පීඩනය 100 kPa, ρ = 1000 kg m⁻³, g = 10)", "200 kPa", "100 kPa", "10 kPa", "300 kPa", "මුළු පීඩනය = වායුගෝලීය පීඩනය + ජල පීඩනය = 100 kPa + (10 × 1000 × 10 Pa) = 200 kPa."),
    q("තියුණු පිහියකින් පාන් හෝ පළතුරු කැපීම මොට පිහියකට වඩා ඉතා පහසු වන්නේ ඇයි?", "වර්ගඵලය කුඩා නිසා කුඩා බලයකින් වැඩි පීඩනයක් යෙදීම", "තියුණු පිහියේ මුළු බර ඉතා වැඩි වීම නිසා", "කැපීමට පෙර පාන් පෙති මෘදු බවට පත් වීම නිසා", "තලය හා පාන් අතර ඝර්ෂණය ඉතා වැඩි වීම නිසා", "P = F / A නිසා වර්ගඵලය අඩු වන විට පීඩනය ඉතා ඉහළ යයි."),
    q("මඩ සහිත පොළොවක ගමන් කරන ට්‍රැක්ටරයක පිටුපස රෝද ඉතා පළල්ව හා විශාලව සාදා ඇත්තේ ඇයි?", "පොළොව මත පීඩනය අඩු කර රෝද එරීම වැළැක්වීමට", "ට්‍රැක්ටරයේ ගමන් වේගය දෙගුණ කර ගැනීමට", "පොළොව මත යෙදෙන සිරස් පීඩනය වැඩි කිරීමට", "ට්‍රැක්ටරයේ සම්පූර්ණ බර ඉහළ නැංවීමට", "විශාල පාදම වර්ගඵලය බර පැතිරවීමෙන් පීඩනය අඩු කරයි."),
    q("ගෘහස්ථ ගෑස් ලිපක හෝ කර්මාන්තශාලා නලයක ගෑස් පීඩනය වායුගෝලීය පීඩනය සමඟ සසඳා මැනීමට ගන්නා U-හැඩැති උපකරණය කුමක්ද?", "මනෝමීටරය (Manometer)", "හයිඩ්‍රෝමීටරය", "ඇනිමෝමීටරය", "සිමෙන්ති මානය", "U-නලයේ ද්‍රව මට්ටම් වෙනස hρg මගින් අතිරික්ත පීඩනය ලබා දේ."),
    q("නලයකින් වතුර හෝ පැට්‍රල් ඇද ගැනීමට භාවිත කරන 'සයිපනය' (Siphon) සහ බීම බටය (Straw) ක්‍රියා කරන්නේ කුමක් මතද?", "වායුගෝලීය පීඩනයේ ක්‍රියාකාරීත්වය", "පෘථිවි චුම්භක ආකර්ෂණ බලය", "ද්‍රවයේ පෘෂ්ඨික ආතතිය පමණක්", "නළය තුළ ඇතිවන කේශාකර්ෂණය", "බටය තුළ පීඩනය අඩු කළ විට පිටත වායුගෝලීය පීඩනය ද්‍රවය ඉහළට තල්ලු කරයි."),
    q("වස්තුවක චලිත සමීකරණවල 's = ut + ½at²' සූත්‍රය භාවිත කළ හැක්කේ කුමන තත්ත්වයක් යටතේද?", "වස්තුව ඒකාකාර ත්වරණයකින් ගමන් කරන විට පමණි", "ත්වරණය කාලය සමඟ අනියමිතව වෙනස් වන විට", "නියත වේගයෙන් වෘත්තාකාර චලිතයේ යෙදෙන විට", "බල සමතුලිතතාවයේ නිසලව පවතින විට පමණි", "නිදහසේ වැටෙන වස්තු (g ≈ නියත) සඳහා ද මෙම සමීකරණය වලංගු වේ."),
    q("වීදුරුවක් මත කාඩ්පතක් තබා ඒ මත කාසියක් තබා, කාඩ්පතට ඇඟිල්ලෙන් වේගයෙන් ගැසූ විට කාසිය කෙළින්ම වීදුරුව තුළට වැටෙන්නේ ඇයි?", "නිශ්චලතා අවස්ථිතිය නිසා කාසිය නිසලව සිටීම", "කාසිය මත ක්‍රියා කරන චුම්භක බලය නිසා", "කාසිය කාඩ්පත මත ඇලී නොසිටීම පමණක් නිසා", "කාඩ්පත වටා ඇති වායු ප්‍රතිරෝධය නිසා", "කෙටි කාලය නිසා කාසිය මත තිරස් ආවේගය ඉතා අල්ප වේ."),
    q("ස්කන්ධය 2 kg වන තුවක්කුවකින් ස්කන්ධය 10 g වන උණ්ඩයක් 400 m s⁻¹ වේගයෙන් වෙඩි තබයි. තුවක්කුව පසුපසට විසි වන (Recoil) ප්‍රවේගය කීයද?", "2 m s⁻¹", "4 m s⁻¹", "20 m s⁻¹", "0.5 m s⁻¹", "M V = m v → 2 × V = 0.01 × 400 → 2V = 4 → V = 2 m s⁻¹."),
    q("පොළොවේ සිට සිරස්ව ඉහළට විසි කළ වස්තුවක් ආපසු අතට වැටීමට මුළු තත්පර 8 ක් ගත වේ නම්, එය ළඟා වූ උපරිම උස කීයද? (g = 10 m s⁻²)", "80 m", "40 m", "160 m", "320 m", "ඉහළට යාමට කාලය = 8/2 = 4 s; h = ½gt² = ½ × 10 × 4² = 80 m."),
    q("1 kg ස්කන්ධයක් ඇති වස්තුවක් පොළොව මත 9.8 N බරකින් යුතු වේ. මෙමඟින් ඒ ස්ථානයේ ගුරුත්වජ ත්වරණය ගැන කිව හැක්කේ කුමක්ද?", "g = 9.8 m s⁻² වන බව", "g = 1.0 m s⁻² වන බව", "ස්කන්ධය 9.8 kg බව", "ඝනත්වය 9.8 බව", "W = mg → 9.8 = 1 × g → g = 9.8 m s⁻²."),
    q("ඒකාකාර ලෙස වේගය වැඩි කරමින් යන වස්තුවක චලිතය පෙන්වන විස්ථාපන-කාල (s-t) ප්‍රස්තාරයේ හැඩය කෙබඳුද?", "ක්‍රමයෙන් අනුක්‍රමණය වැඩි වන පරාවලයික වක්‍රයක්", "තිරස් සෘජු රේඛාවක්", "ආනත සෘජු රේඛාවක්", "පහළට බසින සෘජු රේඛාවක්", "s ∝ t² බැවින් අනුක්‍රමණය (ප්‍රවේගය) කාලයත් සමඟ වැඩි වේ."),
    q("කිසියම් වස්තුවකට ක්‍රියා කරන බල තුනක් එකම තලයක පිහිටා සමතුලිතව පවතී නම්, එම බල ත්‍රිකෝණයක් ලෙස ඇඳිය හැකි වීම හඳුන්වන්නේ කෙසේද?", "බල ත්‍රිකෝණ ප්‍රමේයය", "පයිතගරස් ප්‍රමේයය", "ආකිමිඩීස් නියමය", "හුක්ගේ නියමය", "සංවෘත බල ත්‍රිකෝණයක් සාදන විට සම්ප්‍රයුක්ත බලය ශුන්‍ය වේ."),
    q("වීදුරුවක ඇති ද්‍රවයක් තුළ කිසියම් ගැඹුරකදී සිදුවන පීඩනය සම්බන්ධයෙන් සත්‍ය වන්නේ කුමක්ද?", "සෑම දිශාවකටම සමාන වී හැඩය මත රඳා නොපවතී", "පටු භාජනයේ පීඩනය පළල් භාජනය මෙන් දස ගුණයකි", "ද්‍රව පීඩනය සැමවිටම පහළ දිශාවට පමණක් ක්‍රියා කරයි", "පීඩනය ද්‍රවයේ වර්ණය හා පාරදෘශ්‍ය බව මත රඳා පවතී", "P = hρg රඳා පවතින්නේ සිරස් උස (h), ඝනත්වය (ρ) හා g මත පමණි."),
    q("හයිඩ්‍රොලික් ඔසවනයක් (Hydraulic lift) ක්‍රියා කිරීමේදී යොදා ගන්නා තරලය විය යුත්තේ කුමන ගුණයෙන් යුත් එකක්ද?", "අසම්පීඩ්‍ය ද්‍රව වර්ගයක් (තෙල්)", "පහසුවෙන් සම්පීඩනය වන වායු මිශ්‍රණයක්", "ඝන අංශු අඩංගු හුණු මිශ්‍රණයක්", "සියුම්ව අඹරන ලද වියළි ඝන වැලි", "වාතය සම්පීඩ්‍ය බැවින් තිරිංග නල තුළ වායු බුබුළු ඇති වුවහොත් තිරිංග අක්‍රීය වේ."),
    q("දී ඇති වස්තු දෙකක් 20 N සහ 15 N ලෙස එකම ලක්ෂ්‍යයක එකම දිශාවට ක්‍රියා කරයි. ඒවායේ සම්ප්‍රයුක්තය කීයද?", "35 N", "5 N", "300 N", "25 N", "එකම දිශාවට ක්‍රියා කරන බල සරලව එකතු වේ (20 + 15 = 35 N)."),
    q("කිලෝවොට් පැය (1 kWh) යනු නිවසේ විදුලි මීටරයේ 'ඒකක 1' කි. එය භෞතික විද්‍යාවේ කුමන රාශියේ ඒකකයක්ද?", "ශක්තියේ (විද්‍යුත් ශක්තිය)", "ක්ෂමතාවයේ", "බලයේ", "විදුලි ධාරාවේ", "1 kWh = 1000 W × 3600 s = 3.6 × 10⁶ J (මෙගාජූල් 3.6)."),
    q("වීදුරුවක ඇති 500 g ස්කන්ධයක් පොළොවේ සිට 4 m ඉහළට එසවූ විට එහි විභව ශක්තිය වැඩිවීම කීයද? (g = 10 m s⁻²)", "20 J", "2000 J", "200 J", "2 J", "m = 0.5 kg -> ΔEₚ = 0.5 × 10 × 4 = 20 J."),
    q("පළල 0.5 m හා දිග 1 m වන ගඩොල් බිත්තියකට වඩා 15 cm හරස්කඩකින් යුත් ගැහැණු ළමයෙකුගේ අඩි උස සපත්තු අඩියෙන් පොළොවට වැඩි පීඩනයක් යෙදෙන්නේ ඇයි?", "සපත්තු අඩියේ වර්ගඵලය ඉතා කුඩා බැවින් (P = F/A)", "සපත්තුවේ බර ගඩොල් බිත්තියට වඩා වැඩි නිසා", "ගුරුත්වය එතැන වැඩි නිසා", "සපත්තුව රබර් වීම නිසා", "ලී පොළොව මත පැල්ලම් හිටින්නේ මෙම අධි පීඩනය නිසාය."),
    q("බල ඝූර්ණය වැඩි කිරීම සඳහා සාමාන්‍ය කතුරකට වඩා දැඩි ලෝහ තහඩු කපන කතුරක (Tin snips) මිටවල් දිගටත් තල කෙටියටත් සාදා ඇත්තේ ඇයි?", "ආයාස බාහුව දිගු කර විශාල යාන්ත්‍රික වාසියක් ගැනීමට", "ලෝහ කපන කතුරේ සම්පූර්ණ බර සැහැල්ලු කර ගැනීමට", "තල කෙටි විට කතුරේ වානේ ඉක්මනින් මලකඩ නොකන නිසා", "යන්ත්‍රයේ ප්‍රවේග අනුපාතය හරියටම 1 ලෙස තබා ගැනීමට", "අඩු අත් බලයකින් ලෝහ තහඩු මත ඉතා විශාල කැපුම් බලයක් යෙදේ."),
    q("වීදුරු දණ්ඩක් වැනි කිසියම් දණ්ඩකට දෙපසින් සමාන ආතති බල යොදා ඇද්ද විට, සීමාව තුළදී විතතිය (දිග වැඩිවීම) යෙදූ බලයට අනුලෝමව සමානුපාතික බව කියවෙන නියමය කුමක්ද?", "හුක්ගේ නියමය (Hooke's law)", "නිව්ටන්ගේ දෙවන නියමය", "පැස්කල් නියමය", "බොයිල් නියමය", "F = k x (මෙහි k යනු දුනු නියතයයි)."),
    q("සරල දුන්නකට 10 N බරක් එල්ලූ විට එය 2 cm කින් ඇදේ. හුක්ගේ නියමය පිළිපදී නම් 25 N බරක් එල්ලූ විට ඇදෙන ප්‍රමාණය කීයද?", "5 cm", "4 cm", "10 cm", "2.5 cm", "10 N ට 2 cm නම් 1 cm ට 5 N කි; 25 / 5 = 5 cm."),
    q("සරල අවලම්බයක (Pendulum) බර ගෝලය මධ්‍ය පිහිටුම පසු කරන මොහොතේදී උපරිම වන ශක්ති ආකාරය කුමක්ද?", "චාලක ශක්තිය", "ගුරුත්වාකර්ෂණ විභව ශක්තිය", "ප්‍රත්‍යාස්ථ විභව ශක්තිය", "තාප ශක්තිය", "අන්ත ලක්ෂ්‍ය දෙකේදී විභව ශක්තිය උපරිම වන අතර පහළම මධ්‍යයේදී චාලක ශක්තිය උපරිම වේ."),
    q("පොළොවේ සිට අභ්‍යවකාශයට යන විට වස්තුවක ස්කන්ධය නොවෙනස්ව පවතින අතර ගුරුත්වජ ත්වරණය (g) වෙනස් වන්නේ කෙසේද?", "දුර වැඩි වත්ම g අගය ක්‍රමයෙන් අඩු වේ", "දුර වැඩි වත්ම g අගය ක්‍රමයෙන් වැඩි වේ", "ස්ථානය අනුව කිසිසේත් වෙනස් නොවී පවතී", "ඉහළ යත්ම g අගය ක්ෂණිකව සෘණ බවට පත් වේ", "පෘථිවි කේන්ද්‍රයේ සිට දුර වැඩි වත්ම ගුරුත්වාකර්ෂණ බලය දුර්වල වේ."),
    q("නිව්ටන්ගේ දෙවන නියමය අනුව බලය (F) අර්ථ දැක්වෙන්නේ කුමන සීඝ්‍රතාවක් ලෙසද?", "ගම්‍යතාව වෙනස් වීමේ සීඝ්‍රතාව", "වේගය වෙනස් නොවීමේ සීඝ්‍රතාව", "කාර්යය කිරීමේ සීඝ්‍රතාව", "දුර ගමන් කිරීමේ සීඝ්‍රතාව", "F = (mv - mu) / t = ma."),
    q("සමුද්‍ර මට්ටමේ පිහිටි රසදිය බැරෝමීටර නළය ඇල කර තැබූ විට නළයේ පතුලේ සිට සිරස් රසදිය කඳේ උසට කුමක් සිදුවේද?", "සිරස් උස 76 cm ලෙසම නොවෙනස්ව පවතී", "සිරස් උස පෙර අගයෙන් අඩකින් අඩු වේ", "රසදිය කඳේ සිරස් උස 100 cm වේ", "නළයේ ඇති රසදිය සම්පූර්ණයෙන් පිටාර ගලයි", "ද්‍රවස්ථිති පීඩනය රඳා පවතින්නේ සිරස් උස (h) මත පමණි."),
    q("කිසියම් ද්‍රවයක හා වායුවක ගිලී ඇති වස්තුවක ඝනත්වය ද්‍රවයේ ඝනත්වයට හරියටම සමාන නම් වස්තුව පවතින්නේ කෙසේද?", "ද්‍රවය තුළ සම්පූර්ණයෙන් ගිලී සමතුලිතව පාවෙයි", "ද්‍රව පෘෂ්ඨයෙන් ඉහළට මතු වී පාවෙමින් පවතී", "වේගයෙන් පතුලටම කිඳා බැස පතුලේ රැඳී සිටී", "ක්ෂණිකව වාෂ්ප වී වායුගෝලයට එක් වී යයි", "වස්තුවේ බර හා උඩුකුරු තෙරපුම හරියටම සමාන වේ."),
    q("වාහනයක් නියත 15 m s⁻¹ ප්‍රවේගයෙන් රළු තිරස් මාර්ගයක ගමන් කරයි. එහි එන්ජිම මගින් ඉදිරියට 2500 N බලයක් යොදයි නම්, චලිතයට විරුද්ධ මුළු ප්‍රතිරෝධී බලය කීයද?", "2500 N", "0 N", "5000 N", "1250 N", "ප්‍රවේගය නියත බැවින් සම්ප්‍රයුක්ත බලය 0 විය යුතුය; එනම් ඉදිරි බලය = ප්‍රතිරෝධී බලය."),
    q("මයික්‍රෝමීටර ඉස්කුරුප්පු ආමානයක තිම්බලයේ (වෘත්තාකාර පරිමාණයේ) කොටස් 50 ක් ඇති අතර එක් සම්පූර්ණ වටයකින් ඉස්කුරුප්පුව 0.5 mm ඉදිරියට යයි. කුඩාම මිනුම කීයද?", "0.01 mm", "0.1 mm", "0.5 mm", "0.05 mm", "කුඩාම මිනුම = පිච් / කොටස් ගණන = 0.5 / 50 = 0.01 mm."),
    q("සෘජු මාර්ගයක ගමන් කරන දුම්රියක් 20 m s⁻¹ වේගයෙන් තත්පර 10 ක් ගමන් කර, පසුව 30 m s⁻¹ වේගයෙන් තවත් තත්පර 10 ක් ගමන් කළේය. මුළු ගමනේ සාමාන්‍ය වේගය කීයද?", "25 m s⁻¹", "50 m s⁻¹", "10 m s⁻¹", "20 m s⁻¹", "මුළු දුර = (20×10) + (30×10) = 500 m; මුළු කාලය = 20 s; සාමාන්‍ය වේගය = 500 / 20 = 25 m s⁻¹."),
    q("කිසියම් වස්තුවක ඒකාකාර වේගය 54 km h⁻¹ නම් එය තත්පර 10 කදී ගමන් කරන දුර කීයද?", "150 m", "540 m", "15 m", "180 m", "54 km h⁻¹ = 54 × (5/18) = 15 m s⁻¹; දුර = 15 × 10 = 150 m."),
    q("නිසලව පැවති 3 kg බෝලයකට 6 N ක තිරස් බලයක් තත්පර 5 ක් යෙදූ විට බෝලය අත්පත් කරගන්නා ප්‍රවේගය කීයද?", "10 m s⁻¹", "2 m s⁻¹", "18 m s⁻¹", "30 m s⁻¹", "a = F/m = 6/3 = 2 m s⁻²; v = u + at = 0 + 2 × 5 = 10 m s⁻¹."),
    q("ප්‍රවේග-කාල ප්‍රස්තාරයක කාල අක්ෂයට පහළින් ඇඳ ඇති කොටසකින් නිරූපණය වන්නේ කුමක්ද?", "ප්‍රතිවිරුද්ධ දිශාවට චලනය වීම", "වස්තුව සම්පූර්ණයෙන් නැවතී සිටීම", "වස්තුවේ මුළු ස්කන්ධය අඩු වීම", "වස්තුවේ ගමන් වේගය අනන්ත වීම", "ඉහළට විසි කර නැවත පහළට වැටෙන පන්දුවක ආපසු ගමන සෘණ ප්‍රවේගයකින් පෙන්වයි."),
    q("එක්තරා වාහනයක ස්කන්ධය දෙගුණ කර එහි ප්‍රවේගය අඩකින් අඩු කළහොත් එහි ගම්‍යතාවයට සිදුවන්නේ කුමක්ද?", "වෙනස් නොවේ (පෙර අගයටම සමානය)", "දෙගුණ වේ", "හතර ගුණ වේ", "අඩකින් අඩු වේ", "නව ගම්‍යතාව = (2m) × (v/2) = mv."),
    q("දෙදෙනෙක් (40 kg හා 60 kg) ලිස්සන අයිස් මත මුහුණට මුහුණ ලා සිට එකිනෙකා තල්ලු කරයි. වැඩිම ආරම්භක ත්වරණයක් ලබන්නේ කවුද?", "40 kg පුද්ගලයා වැඩි ත්වරණයකින් යයි", "60 kg පුද්ගලයා වැඩි ත්වරණයකින් යයි", "දෙදෙනාම එකම සමාන ත්වරණයකින් යයි", "දෙදෙනාගෙන් කිසිවෙක් චලනය නොවේ", "ක්‍රියාව හා ප්‍රතික්‍රියාව සමාන බැවින් a = F/m අනුව ස්කන්ධය අඩු පුද්ගලයාට වැඩි ත්වරණයක් ලැබේ."),
    q("L-හැඩැති හෝ ත්‍රිකෝණාකාර සමතල තහඩුවක ගුරුත්ව කේන්ද්‍රය (Center of gravity) ප්‍රායෝගිකව සොයා ගැනීමට භාවිත කරන ක්‍රමය කුමක්ද?", "ලක්ෂ්‍ය කිහිපයකින් එල්ලා ලම්බ රේඛා ඡේදනය සෙවීම", "තහඩුව ජල භාජනයක සම්පූර්ණයෙන් ගිල්වා බැලීම", "මීටර රූලකින් තහඩුවේ පරිමිතිය මැද සෙවීම", "තහඩුවේ කෙළවරට ප්‍රබල චුම්භකයක් අල්ලා බැලීම", "ගුරුත්ව කේන්ද්‍රය සැමවිටම එල්ලුම් ලක්ෂ්‍යයට කෙළින්ම පහළින් ලම්බ රේඛාව මත පිහිටයි."),
    q("රළු ආනත තලයක් මත වස්තුවක් ඉහළට ඇදගෙන යාමේදී එම යන්ත්‍රයේ කාර්යක්ෂමතාව 100% ට වඩා අඩු වීමට ප්‍රධාන හේතුව කුමක්ද?", "ඝර්ෂණය පරාජය කිරීමට අමතර කාර්යයක් වැය වීම", "වස්තුව මත ගුරුත්ව බලය සම්පූර්ණයෙන් නැති වීම", "ආනත තලයේ මුළු දිග අනවශ්‍ය ලෙස වැඩි වීම", "තලය මත තැබූ වස්තුවේ මුළු බර ශුන්‍ය වීම", "ඝර්ෂණය අඩු කිරීමට රෝද හෝ තෙල් භාවිත කළ හැක."),
    q("මිටි හා කියත්වලට මෙන් කුඤ්ඤයක් (Wedge) සහ ඉස්කුරුප්පු ජැක් එකක් කුමන මූලික සරල යන්ත්‍රයේ විශේෂිත ආකාර දෙකක්ද?", "ආනත තලය (Inclined plane)", "චල කප්පිය", "සමතල දර්පණය", "හයිඩ්‍රොලික් පිස්ටනය", "ඉස්කුරුප්පුවක් යනු සිලින්ඩරයක් වටා ඔතන ලද ආනත තලයකි."),
    q("ස්ථිරව පොළොවට සවි කළ පාලම් හා ගොඩනැගිලි කණුවල හරස්කඩ 'I-හැඩැති' හෝ 'T-හැඩැති' වානේ බාල්කවලින් සාදන්නේ ඇයි?", "අඩු ද්‍රව්‍ය හා බරකින් නැමීමට එරෙහි උපරිම ශක්තිය ගැනීමට", "පාලම් හා ගොඩනැගිලිවලට අලංකාර පෙනුමක් ලබා දීමට", "වානේ බාල්ක ඔස්සේ විදුලි ධාරාව පහසුවෙන් සන්නයනයට", "වානේ බාල්ක මත ඉක්මනින් මලකඩ බැඳීම වළක්වා ගැනීමට", "ඉහළ හා පහළ දාර ආතතිය හා සම්පීඩනය දරා ගනී."),
    q("වීදුරුවක් තුළ ඇති රසදිය බැරෝමීටරයක් වෙනුවට, නිවසේ හෝ කඳු නගින්නන් අතේ ගෙන යන ද්‍රව රහිත වායු පීඩනමානය කුමක්ද?", "ඇනරොයිඩ් බැරෝමීටරය", "සාමාන්‍ය හයිඩ්‍රෝමීටරය", "U-නල මනෝමීටරය", "ශාක පෝටෝමීටරය", "රික්ත කළ නැමෙනසුලු ලෝහ පෙට්ටියක් පීඩනය අනුව හැකිලීමෙන් දර්ශක කටුව චලනය වේ."),
    q("ඝනත්වය 800 kg m⁻³ වන ද්‍රවයක් 0.5 m ගැඹුරකදී ඇති කරන ද්‍රවස්ථිති පීඩනය කීයද? (g = 10 m s⁻²)", "4,000 Pa", "400 Pa", "1,600 Pa", "8,000 Pa", "P = hρg = 0.5 × 800 × 10 = 4,000 Pa."),
    q("රබර් බෝලයක් ජලය තුළට බලයෙන් ගිල්වා අතහැරිය විට එය වේගයෙන් ඉහළට මතු වන්නේ ඇයි?", "බෝලය මත උඩුකුරු තෙරපුම එහි බරට වඩා වැඩි නිසා", "බෝලයේ ගුරුත්වාකර්ෂණ බර ඉහළට ක්‍රියා කරන නිසා", "බෝලය අවට ඇති ජලය ඇතුළට උරා ගන්නා නිසා", "ජලය තුළ ඇති වායු පීඩනය සම්පූර්ණයෙන් ශුන්‍ය නිසා", "ශුද්ධ බලය ඉහළට ක්‍රියා කරන බැවින් බෝලය ත්වරණයෙන් ඉහළට පැමිණේ."),
    q("සබ්මැරීනයක් සාගරයේ ගැඹුරට කිමිදීමට සහ නැවත ජල මතුපිටට පැමිණීමට එහි 'බැලස්ට් ටැංකි' (Ballast tanks) තුළට සිදු කරන්නේ කුමක්ද?", "ගිලීමට ජලය පුරවා පාවීමට සම්පීඩිත වාතයෙන් ජලය පිට කරයි", "ටැංකි තුළට අධික ඝනත්වයකින් යුත් තෙල් පුරවයි", "සබ්මැරීනය සැහැල්ලු කිරීමට බර යකඩ පිටතට විසි කරයි", "ඉහළට එසවීමට ප්‍රධාන එන්ජිම ආපසු දිශාවට කරකවයි", "ජලය පිරවූ විට සබ්මැරීනයේ මුළු බර උඩුකුරු තෙරපුම ඉක්මවා යයි."),
    q("නොනැසී ගලා යන ගංගාවක පළල අඩු පටු කොටසකදී ජලය ගලා යන වේගය වැඩි වන අතර එතැන ජල පීඩනයට කුමක් සිදුවේද? (බර්නූලි මූලධර්මය)", "පීඩනය අඩු වේ", "පීඩනය වැඩි වේ", "පීඩනය දෙගුණ වේ", "වෙනස් නොවේ", "වේගය වැඩි වන කලාපයේ තරල පීඩනය අඩු වේ."),
    q("කෘමිනාශක ඉසින යන්ත්‍ර (Sprayers) සහ බුන්සන් දාහකය ක්‍රියා කරන්නේ කුමන භෞතික විද්‍යා මූලධර්මය මතද?", "බර්නූලි මූලධර්මය (වේගවත් වායු අඩු පීඩනය)", "ආකිමිඩීස්ගේ උඩුකුරු තෙරපුම් මූලධර්මය", "හුක්ගේ ප්‍රත්‍යාස්ථතා සීමා නියමය", "විද්‍යුත් චුම්භක ප්‍රේරණ ලෙන්ස් නියමය", "නළ කෙළවර වේගයෙන් යන වාතය නිසා අඩු පීඩනයක් ඇති වී ද්‍රවය හෝ වාතය ඉහළට ඇද ගනී."),
    q("කිසියම් ද්‍රව්‍යයක් මත '15 N' හා '15 N' සමාන බල දෙකක් එකම ලක්ෂ්‍යයක ප්‍රතිවිරුද්ධ දිශාවට ක්‍රියා කරයි. වස්තුවේ ත්වරණය කීයද?", "0 m s⁻²", "30 m s⁻²", "15 m s⁻²", "1 m s⁻²", "සම්ප්‍රයුක්ත බලය = 15 - 15 = 0 N බැවින් a = 0 m s⁻²."),
    q("සිරස්ව පිහිටි ජල නලයක පතුලේදී 80,000 Pa පීඩනයක් ඇති නම් ජල කඳේ උස කීයද? (ρ = 1000 kg m⁻³, g = 10 m s⁻²)", "8 m", "80 m", "0.8 m", "800 m", "h = P / (ρg) = 80,000 / (1000 × 10) = 8 m."),
    q("1 kg ස්කන්ධයක් ඇති වස්තුවක් පොළොව මතදී 5 m s⁻¹ වේගයෙන් ගොස් තත්පර 2 කින් 15 m s⁻¹ දක්වා ත්වරණය වේ. එහි චාලක ශක්ති වැඩිවීම කීයද?", "100 J", "125 J", "112.5 J", "50 J", "ΔEₖ = ½m(v² - u²) = ½ × 1 × (225 - 25) = ½ × 200 = 100 J."),
    q("ගල් කැටයක් අතේ තබා 20 m s⁻¹ වේගයෙන් කෙළින්ම ඉහළට විසි කළේය. ගල් කැටය ළඟා වන උපරිම උස කීයද? (g = 10 m s⁻²)", "20 m", "40 m", "10 m", "200 m", "v² = u² - 2gh → 0 = 20² - 2(10)h → 20h = 400 → h = 20 m."),
    q("වීදුරුවක ඇති ඝන ලෝහ කැබැල්ලක් සඳ මතුපිටට ගෙන ගොස් දුනු තරාදියකින් (Spring balance) කිරූ විට පොළොවට වඩා කුමන වෙනසක් දැකිය හැකිද?", "පාඨාංකය පොළොවේ අගයෙන් 1/6 ක් ලෙස අඩු වේ", "පාඨාංකය 6 ගුණ වේ", "පාඨාංකය නොවෙනස්ව පවතී", "තරාදිය 0 පෙන්වයි", "දුනු තරාදිය මගින් මනින්නේ ගුරුත්වාකර්ෂණය මත රඳා පවතින බර (W = mg) වේ."),
    q("මූලික ඒකක ඇසුරින් 'ජූල් 1' (1 J) යන්න ප්‍රකාශ කළ විට නිවැරදි ප්‍රකාශනය කුමක්ද?", "1 kg m² s⁻²", "1 kg m s⁻²", "1 kg m s⁻¹", "1 kg m² s⁻³", "W = F × s = (kg m s⁻²) × m = kg m² s⁻²."),
    q("ඒකාකාර මීටර රූලක් 50 cm ලකුණෙන් සමතුලිතව පවතී. රූලේ බර 1 N නම් 20 cm ලකුණේ 3 N බරක් එල්ලූ විට සමතුලිතතාව රැක ගැනීමට 80 cm ලකුණේ එල්ලිය යුතු බර කීයද?", "3 N", "1 N", "6 N", "1.5 N", "දෙකම 50 cm මැද සිට 30 cm දුරින් පිහිටන බැවින් 3 × 30 = W × 30 → W = 3 N."),
    q("ඒකාකාර නොවන දණ්ඩක එක් කෙළවරක සිට 30 cm දුරින් පිහිටි ලක්ෂ්‍යයකදී දණ්ඩ තනිවම තිරස්ව සමතුලිත වේ නම් එම ලක්ෂ්‍යය කුමක්ද?", "දණ්ඩේ ගුරුත්ව කේන්ද්‍රය", "දණ්ඩේ මධ්‍ය ලක්ෂ්‍යය", "දණ්ඩේ ආයාසය", "දණ්ඩේ ක්ෂමතාව", "මුළු බර ක්‍රියා කරන බවට සලකන ලක්ෂ්‍යය මත සමතුලිත කළ විට ශුද්ධ ඝූර්ණය ශුන්‍ය වේ."),
    q("වේගය 36 km h⁻¹ වූ බයිසිකලයක් ත්වරණය 2 m s⁻² කින් තත්පර 5 ක් ගමන් කළ විට එහි නව ප්‍රවේගය කීයද?", "20 m s⁻¹", "46 m s⁻¹", "10 m s⁻¹", "26 m s⁻¹", "u = 36 km h⁻¹ = 10 m s⁻¹; v = 10 + (2 × 5) = 20 m s⁻¹."),
    q("සරල කප්පි දෙකකින් යුත් කප්පි පද්ධතියකින් (VR = 2) 150 N බරක් 2 m ඉහළට එසවීමට ආයාසය 100 N යෙදිය යුතු නම් කාර්යක්ෂමතාව කීයද?", "75%", "100%", "66.7%", "50%", "MA = 150 / 100 = 1.5; η = (1.5 / 2) × 100% = 75%."),
    q("කිසියම් වස්තුවක් දිග 10 m, පළල 5 m හා උස 2 m වූ ටැංකියක ජලය සම්පූර්ණයෙන් පිරී ඇත. එහි ඇති ජලයේ මුළු ස්කන්ධය කීයද? (ρ = 1000 kg m⁻³)", "100,000 kg (ටොන් 100)", "10,000 kg", "100 kg", "1,000,000 kg", "පරිමාව V = 10 × 5 × 2 = 100 m³; m = ρV = 1000 × 100 = 100,000 kg."),
    q("දැඩි ශීතල කාලගුණයක කඳු නගින විට මිනිසුන්ගේ නාසයෙන් ලේ ගැලීමට ඉඩ ඇත්තේ කුමන භෞතික හේතුව නිසාද?", "බාහිර වායු පීඩනය අඩු වී සියුම් රුධිර නාල පුපුරා යාම", "ඉහළ උන්නතාංශයේදී වාතයේ ඝනත්වය දෙගුණයක් වීම", "පෘථිවි ගුරුත්වාකර්ෂණ බලය සම්පූර්ණයෙන් ශුන්‍ය වීම", "රුධිරය තුළ ඇති රසදිය ප්‍රමාණය ක්ෂණිකව වැඩි වීම", "ඉහළ උසකදී වායුගෝලීය පීඩනය සැලකිය යුතු ලෙස පහත බසී."),
    q("කිසියම් සිරස් බිත්තියකට එල්ලූ වානේ පටියක හරස්කඩ වර්ගඵලය අඩු කළහොත් සමාන බරකින් ඇති වන ආතති පීඩනයට කුමක් සිදුවේද?", "පීඩනය වැඩි වේ", "පීඩනය අඩු වේ", "වෙනස් නොවේ", "ශුන්‍ය වේ", "ආතතිය = බලය / වර්ගඵලය."),
    q("ද්‍රවස්ථිති පරීක්ෂණයේදී එකම උසකට ජලය පුරවා ඇති විවිධ හැඩැති සම්බන්ධිත භාජන (Communicating vessels) කිහිපයක ද්‍රව මට්ටම් කෙබඳුද?", "සෑම භාජනයකම ද්‍රව මට්ටම එකම තිරස් උසක පිහිටයි", "පළල් භාජනයේ ජල මට්ටම අනෙක්වාට වඩා වැඩි වේ", "පටු නළයේ ජල මට්ටම අනෙක්වාට වඩා පහළින් පිහිටයි", "ඇල කර ඇති නළය තුළ ජලය කිසිසේත් රැඳී නොපවතී", "පතුලේ පීඩනය සමාන වීමට සෑම ශාඛාවකම සිරස් උස (h) සමාන විය යුතුය."),
    q("වස්තුවක චාලක ශක්තිය Eₖ සහ ගම්‍යතාව P අතර සම්බන්ධතාවය කුමක්ද? (ස්කන්ධය m)", "Eₖ = P² / (2m)", "Eₖ = P × m", "Eₖ = 2m / P", "Eₖ = P / m", "P = mv නිසා Eₖ = ½mv² = (m²v²) / (2m) = P² / (2m)."),
    q("ස්කන්ධය 4 kg වූ වස්තුවක ගම්‍යතාව 20 kg m s⁻¹ නම් එහි චාලක ශක්තිය කීයද?", "50 J", "100 J", "200 J", "25 J", "v = 20 / 4 = 5 m s⁻¹; Eₖ = ½ × 4 × 5² = 50 J."),
    q("ඝනත්වය 900 kg m⁻³ වූ අයිස් කුට්ටියක් ජලයේ (1000 kg m⁻³) පාවෙන විට ජලය මට්ටමෙන් ඉහළට මතු වී පවතින කොටස මුළු පරිමාවෙන් කොපමණ ප්‍රතිශතයක්ද?", "10%", "90%", "50%", "20%", "ගිලෙන කොටස 900/1000 = 90% බැවින් ඉහළින් මතු වී ඇත්තේ 10% කි (Iceberg මූලධර්මය)."),
    q("ඒකාකාර වෘත්තාකාර චලිතයක යෙදෙන වස්තුවක (උදා: නියත වේගයෙන් වංගුවක් ගන්නා රථයක්) ත්වරණයක් පවතින බව කියන්නේ ඇයි?", "වේගය නියත වුවද චලිත දිශාව නොකඩවා වෙනස් වන බැවින්", "රථයේ ගමන් වේගය ක්ෂණිකව දෙගුණ වන බැවින්", "චලනය වන වස්තුවේ මුළු ස්කන්ධය වැඩි වන බැවින්", "වංගුව තුළ කිසිදු බලයක් ක්‍රියා නොකරන බැවින්", "මධ්‍යය දෙසට ක්‍රියා කරන කේන්ද්‍රාභිසාරී බලය (Centripetal force) මෙම ත්වරණය ඇති කරයි."),
    q("ශ්‍රී ලංකාවේ බහුලව භාවිත කරන 'නිව්ටන් මීටර 1' යනු කාර්යයේ ඒකකයක් ලෙස කුමන ඒකකයට සමාන වේද?", "ජූල් 1 (1 J)", "වොට් 1", "පැස්කල් 1", "හර්ට්ස් 1", "1 N බලයකින් 1 m විස්ථාපනය කළ විට 1 J කාර්යයක් සිදුවේ."),
    q("කිසියම් බස් රථයක් ආරම්භයේ සිට තත්පර 10 ක් තුළදී 0 සිට 25 m s⁻¹ දක්වා ඒකාකාරව ත්වරණය විය. එම තත්පර 10 තුළ බස් රථය ගිය මුළු දුර කීයද?", "125 m", "250 m", "2.5 m", "500 m", "s = ½(u + v)t = ½(0 + 25) × 10 = 125 m."),
    q("ගිනිගෙන දැවෙන උණුසුම් වායු බැලූනයක් (Hot air balloon) වායුගෝලයේ ඉහළට නගින්නේ කුමන බලය නිසාද?", "වාතයේ උඩුකුරු තෙරපුම බැලූනයේ බරට වඩා වැඩි වීම", "පහළට පිටවන වායු මගින් ඇති වන රොකට් ප්‍රතික්‍රියාව", "පෘථිවියෙන් ඇති වන චුම්භක විකර්ෂණ බලය නිසා", "බැලූනය මතුපිට රැස්වන ස්ථිති විද්‍යුත් ආරෝපණ නිසා", "බැලූනයේ රත් වූ වාතයේ ඝනත්වය පිටත සිසිල් වාතයට වඩා අඩුය."),
    q("සිරස් බිත්තියක් ඉදිරිපිට කඹයකින් 400 N බර පෙට්ටියක් 3 m උස ලොරියකට ඍජුවම ඉහළට එසවීමත්, 6 m දිග සුමට ලෑල්ලක් ඔස්සේ තල්ලු කර ගැනීමත් සැසඳීමේදී සමාන වන්නේ කුමක්ද?", "සිදු කරන මුළු විභව ශක්ති වැඩිවීම (1,200 J)", "පෙට්ටිය මත යෙදිය යුතු ආයාස බලයේ විශාලත්වය", "පෙට්ටිය විසින් ගමන් කරනු ලබන මුළු දුර ප්‍රමාණය", "අවස්ථා දෙකෙහිදී ලැබෙන යාන්ත්‍රික වාසියේ අගය", "සුමට ලෑල්ල දිගේ යෙදිය යුතු බලය 200 N පමණක් වුවද මුළු කාර්යය 200×6 = 1,200 J ලෙසම සමාන වේ."),
    q("කිසියම් වස්තුවක ත්වරණ-කාල ප්‍රස්තාරය හරහා දැක්වෙන නිදහසේ වැටෙන වස්තුවක ත්වරණය 10 m s⁻² ලෙස නියත නම් 5 වන තත්පරය අවසානයේ එහි වේගය කීයද?", "50 m s⁻¹", "125 m s⁻¹", "2 m s⁻¹", "10 m s⁻¹", "v = u + gt = 0 + 10 × 5 = 50 m s⁻¹."),
    q("වානේ පාලමක ඇති රෝලර් බෙයාරිං (Rollers) හා ලිහිසි තෙල් මෙන්, ගුවන් යානා හා මෝටර් රථවල ඉදිරිපස හැඩය 'ධාරා රේඛීය' (Streamlined) ලෙස සාදන්නේ ඇයි?", "වායු ප්‍රතිරෝධය අවම කර ඉන්ධන කාර්යක්ෂමතාව වැඩි කිරීමට", "වාහනය ඉදිරිපස ඇතිවන වායු පීඩනය වැඩි කර ගැනීමට", "වාහනය මත ක්‍රියා කරන ගුරුත්වාකර්ෂණ බලය වැඩි කිරීමට", "ධාවනය වන වේගය පාලනය කර අඩු කර ගැනීමට", "මසුන්ගේ හා පක්ෂීන්ගේ ශරීර හැඩය ද ස්වාභාවික ධාරා රේඛීය අනුවර්තනයකි."),
    q("1.5 m s⁻¹ වේගයෙන් ගලන ගඟක් හරහා එල්ලන ලද සමතුලිත ලෑල්ලක් මත සිටින ළමයෙක් ලෑල්ලේ මැද සිට එක් කෙළවරකට ඇවිද යන විට බිම නොවැටී සිටීමට ආධාරක දෙකෙන් ළං වන ආධාරකය මත ප්‍රතික්‍රියාවට කුමක් වේද?", "ප්‍රතික්‍රියා බලය වැඩි වේ", "ප්‍රතික්‍රියා බලය අඩු වේ", "ප්‍රතික්‍රියා බලය ශුන්‍ය වේ", "ප්‍රතික්‍රියාව වෙනස් නොවේ", "ළමයා ළං වන ආධාරකය වැඩි බර ප්‍රමාණයක් දරා ගනී."),
    q("ස්කන්ධය 2 kg හා 3 kg වන ගැටෙන වස්තු දෙකක් (4 m s⁻¹ හා 0 m s⁻¹) ගැටීමෙන් පසු එකට ඇලී ගමන් කරයි නම් පොදු ප්‍රවේගය කීයද?", "1.6 m s⁻¹", "2.0 m s⁻¹", "4.0 m s⁻¹", "2.67 m s⁻¹", "මුළු ගම්‍යතාව = (2×4) + 0 = 8; මුළු ස්කන්ධය = 5 kg → V = 8 / 5 = 1.6 m s⁻¹."),
    q("මිනුම් උපකරණ අතුරින් වඩාත්ම ඉහළ නිරවද්‍යතාවයකින් යුතුව වර්ග ඵලය හෝ දිග (උදා: 2.34 mm) මැනීමේදී ශුන්‍ය දෝෂය පරීක්ෂා කළ යුතු උපකරණ යුගලය කුමක්ද?", "වර්නියර් කැලිපරය හා මයික්‍රෝමීටරය", "සාමාන්‍ය මීටර කෝදුව සහ නූල", "විද්‍යාගාර ද්‍රවමානය සහ තාපමානය", "දුනු තරාදිය සහ විරාම ඝටිකාව", "හනු සම්පූර්ණයෙන් වසා ඇති විට පාඨාංකය 0.00 නොවේ නම් ශුන්‍ය දෝෂයක් පවතී.")
  )
}
